import {resolve as resolveScriptPath} from "node:path";
import {pathToFileURL as scriptURL} from "node:url";
import { verifyAccountStorage } from "../e2e/account-storage.mjs";
import { randomBytes } from "node:crypto";
import { DatabaseSync } from "node:sqlite";
import { createFixture,safeDiagnostic } from "../e2e/lifecycle.mjs";
import { existsSync,writeFileSync,unlinkSync } from "node:fs";
import { join as pathJoin } from "node:path";
import { createGroup as createLegacyGroup } from "../../lib/groups.ts";
let f,failure,current="setup";
const check=(value,label)=>{if(!value)throw new Error(`Expected ${label}; observed condition false`);};
const step=async(name,run)=>{current=name;await run();console.log(`PASS ${name}`);};
async function capture(context){for(const cookie of await context.cookies())if(!f.secrets.includes(cookie.value))if(cookie.name !== "watchnext_access_mode") f.secrets.push(cookie.value);}
async function register(page,name,password,fromHere=false){if(!fromHere)await page.goto(f.origin+"/register");await page.getByLabel("Username",{exact:true}).fill(name);await page.getByLabel("Password",{exact:true}).fill(password);await page.getByLabel("Confirm password").fill(password);await page.getByRole("button",{name:"Create account",exact:true}).press("Enter");const code=page.getByLabel("Private recovery code");await code.waitFor();const saved=await code.inputValue();f.secrets.push(saved);await capture(page.context());await page.getByRole("link",{name:/Continue/}).press("Enter");await page.waitForURL("**/account");return saved;}
async function login(page,name,password){await page.goto(f.origin+"/login");await page.getByLabel("Username",{exact:true}).fill(name);await page.getByLabel("Password",{exact:true}).fill(password);await page.getByRole("button",{name:"Sign in",exact:true}).press("Enter");await page.waitForURL("**/account");await capture(page.context());}
async function create(page,name){await page.goto(f.origin+"/account");await page.getByLabel("New group name").fill(name);await page.getByRole("button",{name:"Create account group",exact:true}).press("Enter");const input=page.getByLabel("Invite link",{exact:true});await input.waitFor();const invite=await input.inputValue();f.secrets.push(invite.split("/").at(-1));await capture(page.context());return invite;}
async function open(page,name){await page.goto(f.origin+"/account");await page.getByRole("button",{name:`Open ${name}`,exact:true}).press("Enter");await page.waitForURL("**/group");await page.getByRole("heading",{name,exact:true}).waitFor();await capture(page.context());}
async function join(page,invite,name){await page.goto(invite);await page.waitForURL("**/account");await capture(page.context());await page.getByRole("button",{name:`Join ${name}`,exact:true}).press("Enter");await page.waitForURL("**/group");await page.getByRole("heading",{name,exact:true}).waitFor();await capture(page.context());}
async function save(page,title,type="movie",minutes="18",confirmation){await page.goto(f.origin+"/watchlist/add");await page.getByLabel("Title",{exact:true}).fill(title);await page.getByLabel("Content type",{exact:true}).selectOption(type);await page.getByLabel("Minutes",{exact:true}).fill(minutes);if(type==="series")await page.getByLabel("Episode numbering").selectOption("continuous");await page.getByLabel("Funny",{exact:true}).check();await page.getByRole("button",{name:"Save title",exact:true}).press("Enter");if(confirmation)await page.getByRole("button",{name:confirmation,exact:true}).press("Enter");await page.waitForURL(url=>confirmation?/^\/watchlist\/[0-9a-f-]{36}$/.test(url.pathname):url.searchParams.has("saved"));return confirmation?new URL(page.url()).pathname.split("/").at(-1):new URL(page.url()).searchParams.get("saved");}
async function detail(page,id){await page.goto(f.origin+"/watchlist/"+id);}
async function submit(region,button,message){await region.getByRole("button",{name:button,exact:true}).press("Enter");await region.getByText(message,{exact:true}).waitFor();}
async function rotate(page){await page.goto(f.origin+"/group");await page.getByRole("button",{name:"Rotate invite",exact:true}).press("Enter");await page.getByRole("button",{name:"Confirm rotation",exact:true}).press("Enter");const field=page.getByLabel("New invite link",{exact:true});await field.waitFor();const link=await field.inputValue();f.secrets.push(link.split("/").at(-1));await page.getByRole("button",{name:"Copy new invite link",exact:true}).press("Enter");await page.getByRole("status").filter({hasText:/Invite link copied|Select the link/}).waitFor();return link;}
export async function runAccountGroups({build=true,onFixture,injectFailure=false}={}){
failure=undefined;current="setup";

try{
  f=await createFixture();onFixture?.(f);await step(build?"current production build and owned server":"owned server using this invocation's current build",async()=>{await (build?f.build():f.initialize());await f.launch();await f.start();});
  for(const width of [375,1280]){
    const contexts=await Promise.all([f.context(width),f.context(width),f.context(width),f.context(width),f.context(width)]),[a,b,c,a2,b2]=await Promise.all(contexts.map(context=>context.newPage()));
    const names={a:`MemberA.${width}`,b:`MemberB.${width}`,c:`MemberC.${width}`,g1:`Account group one ${width}`,g2:`Account group two ${width}`,movie:`Shared account movie ${width}`,series:`Account series ${width}`,foreign:`Private other group ${width}`};
    const password=randomBytes(24).toString("base64url");f.secrets.push(password);let invite,g1,g2,movie,series,foreign,recoveryCode;
    await step(`${width}: create, signed-out invite registration resume, three accounts and two groups`,async()=>{
      recoveryCode=await register(a,names.a,password);invite=await create(a,names.g1);g1=f.db.prepare("SELECT id FROM groups WHERE name=?").get(names.g1).id;
      await b.goto(invite);await b.waitForURL("**/login");await capture(contexts[1]);check(!(await b.locator("main").textContent()).includes(names.g1),"no private group disclosure before authentication");check(new URL(b.url()).search==="","no raw invite return query");
      await b.getByRole("link",{name:"Create an account",exact:true}).press("Enter");await b.waitForURL("**/register");await register(b,names.b,password,true);await b.getByRole("button",{name:`Join ${names.g1}`,exact:true}).press("Enter");await b.waitForURL("**/group");await capture(contexts[1]);
      await register(c,names.c,password);const second=await create(c,names.g2);g2=f.db.prepare("SELECT id FROM groups WHERE name=?").get(names.g2).id;foreign=await save(c,names.foreign);
      await join(a,second,names.g2);await open(a,names.g1);await login(a2,names.a,password);await open(a2,names.g2);
      await a.reload();await a.getByRole("heading",{name:names.g1,exact:true}).waitFor();check(await a.getByRole("button",{name:/Create and select profile| Select$/}).count()===0,"account identity has no arbitrary profile selection");
      check(f.db.prepare("SELECT count(*) AS n FROM account_memberships WHERE group_id=?").get(g1).n===2,"one stable membership per account/group");
    });
    await step(`${width}: account-derived save, contributor-only editing and independent history`,async()=>{
      movie=await save(b,names.movie);series=await save(b,names.series,"series","20");await detail(a,movie);check(await a.getByRole("link",{name:"Edit title",exact:true}).count()===0,"owner is not implicitly contributor");
      await save(a,names.movie,"movie","18","Add my name to this title");await a.goto(`${f.origin}/watchlist/${movie}/edit`);await a.getByLabel("Genres (optional)",{exact:true}).fill("Shared correction");await a.getByRole("button",{name:"Save changes",exact:true}).press("Enter");await a.waitForURL(`**/watchlist/${movie}`);
      for(const[page,score,note,timestamp]of[[a,"9","Account A own note","0:09"],[b,"6","Account B own note","0:02"]]){
        await detail(page,movie);const rating=page.getByRole("region",{name:"Your rating",exact:true});await rating.getByLabel("Rating (1–10)").fill(score);await submit(rating,"Save rating","Your whole-title rating is saved.");const notes=page.getByRole("region",{name:"Your note",exact:true});await notes.getByLabel("Your note text").fill(note);await submit(notes,"Save note","Your whole-title note is saved.");const progress=page.getByRole("region",{name:"Your watch progress",exact:true});await progress.getByLabel("Stopped at").fill(timestamp);await submit(progress,"Save timestamp","Timestamp saved. Completion is unchanged.");
      }
      const rows=f.db.prepare("SELECT m.name,r.score,n.body,p.timestamp_seconds FROM ratings r JOIN members m ON m.id=r.member_id JOIN notes n ON n.member_id=m.id AND n.title_id=r.title_id JOIN progress p ON p.member_id=m.id AND p.title_id=r.title_id WHERE r.title_id=? ORDER BY m.name").all(movie);check(rows.length===2&&rows[0].score===9&&rows[1].score===6&&rows[0].timestamp_seconds===9&&rows[1].timestamp_seconds===2,"own writes derive actual account members");
    });
    await step(`${width}: real lookup review and full picker with account viewers`,async()=>{
      await a.goto(f.origin+"/watchlist/add");await a.getByLabel("Entry method").selectOption("youtube");await a.getByLabel("YouTube video link or ID").fill("YtFixture01");await a.getByRole("button",{name:"Look up video",exact:true}).press("Enter");await a.locator('input[name="reviewHandle"]').waitFor({state:"attached"});f.secrets.push(await a.locator('input[name="reviewHandle"]').inputValue());await a.getByLabel("Title",{exact:true}).fill(`Account provider ${width}`);await a.getByLabel("Funny",{exact:true}).check();await a.getByRole("button",{name:"Save title",exact:true}).press("Enter");await a.waitForURL("**/watchlist/add?saved=*");
      for(const[page,episode]of[[a,"3"],[b,"7"]]){await detail(page,series);const progress=page.getByRole("region",{name:"Your episode progress",exact:true});await progress.getByLabel("Episode position").selectOption("in_progress");await progress.getByLabel("Next episode to watch").fill(episode);await submit(progress,"Save episode progress","Episode progress saved. Completion is unchanged.");}
      await a.goto(f.origin+"/pick");await a.getByRole("checkbox",{name:names.a,exact:true}).check();await a.getByRole("checkbox",{name:names.b,exact:true}).check();await a.getByLabel("Available time (whole minutes)").fill("20");await a.getByLabel("Mood",{exact:true}).selectOption("funny");await a.getByLabel("Rewatches OK").check();await a.getByRole("button",{name:"Pick for me",exact:true}).press("Enter");await a.getByRole("region",{name:names.series,exact:true}).waitFor();await a.getByText("Episode 3",{exact:true}).waitFor();
    });
    await step(`${width}: stale away/back action replay, other session selection and cross-group isolation`,async()=>{
      await detail(a,movie);let captured;const handler=request=>{if(request.method()==="POST"&&request.headers()["next-action"])captured={headers:request.headers(),body:request.postDataBuffer()};};a.on("request",handler);const rating=a.getByRole("region",{name:"Your rating",exact:true});await rating.getByLabel("Rating (1–10)").fill("8");await submit(rating,"Save rating","Your whole-title rating is saved.");a.off("request",handler);check(captured?.body,"captured actual account server action");
      await open(a,names.g2);await open(a,names.g1);await a2.reload();await a2.getByRole("heading",{name:names.g2,exact:true}).waitFor();
      const cookies=await contexts[0].cookies(),headers={...captured.headers,origin:f.origin,cookie:cookies.map(cookie=>`${cookie.name}=${cookie.value}`).join("; ")};for(const key of["host","content-length","connection"])delete headers[key];
      const response=await fetch(f.origin+"/watchlist/"+movie,{method:"POST",headers,body:captured.body,signal:AbortSignal.timeout(15000)});check((await response.text()).includes("Your rating is unavailable"),"old bound context rejected after away/back");
      await detail(a,foreign);await a.getByRole("heading",{name:"Title unavailable",exact:true}).waitFor();check(!(await a.locator("main").textContent()).includes(names.foreign),"selected group restricts own other membership reads");await detail(c,movie);await c.getByRole("heading",{name:"Title unavailable",exact:true}).waitFor();
    });
    await step(`${width}: removal, generation-safe same-member rejoin, preserved attribution and explicit legacy mode`,async()=>{
      await login(b2,names.b,password);await open(b2,names.g1);await detail(b2,movie);
      let oldMutation;const remember=request=>{if(request.method()==="POST"&&request.headers()["next-action"])oldMutation={headers:request.headers(),body:request.postDataBuffer()};};b2.on("request",remember);
      const rating=b2.getByRole("region",{name:"Your rating",exact:true});await rating.getByLabel("Rating (1–10)").fill("5");await submit(rating,"Save rating","Your whole-title rating is saved.");b2.off("request",remember);check(oldMutation?.body,"captured second-browser pre-removal mutation");
      const member=f.db.prepare("SELECT m.id FROM members m JOIN account_memberships a ON a.member_id=m.id WHERE m.group_id=? AND m.name=?").get(g1,names.b).id;
      const history=JSON.stringify(f.db.prepare("SELECT * FROM progress WHERE member_id=? ORDER BY title_id").all(member));
      await b.goto(f.origin+"/group");check(await b.getByRole("button",{name:/Remove |Rotate invite/}).count()===0,"noncreator sees no management controls");await a.goto(f.origin+"/group");check(await a.getByRole("button",{name:`Remove ${names.a}`,exact:true}).count()===0,"creator cannot remove self");
      await a.getByRole("button",{name:"Rotate invite",exact:true}).press("Enter");await a.getByRole("button",{name:"Cancel",exact:true}).press("Enter");check(f.db.prepare("SELECT invite_generation FROM groups WHERE id=?").get(g1).invite_generation===1,"rotation cancel writes nothing");
      const beforeRemovalLink=await rotate(a);await a.reload();check(await a.getByLabel("New invite link").count()===0,"new raw invitation cannot be retrieved on reload");
      await b2.goto(beforeRemovalLink);await b2.waitForURL("**/account");await capture(contexts[4]);
      await a.getByRole("button",{name:`Remove ${names.b}`,exact:true}).press("Enter");await a.getByRole("heading",{name:`Remove ${names.b}?`,exact:true}).waitFor();await a.getByRole("button",{name:"Cancel",exact:true}).press("Enter");check(f.db.prepare("SELECT status FROM account_memberships WHERE member_id=?").get(member).status==="active","removal cancel writes nothing");
      const waiting=pathJoin(f.root,"provider-waiting"),release=pathJoin(f.root,"provider-release"),returned=pathJoin(f.root,"provider-returned");for(const file of[waiting,release,returned])if(existsSync(file))unlinkSync(file);
      await b2.goto(f.origin+"/watchlist/add");await b2.getByLabel("Entry method").selectOption("youtube");await b2.getByLabel("YouTube video link or ID").fill("YtHolding01");await b2.getByRole("button",{name:"Look up video",exact:true}).press("Enter");
      const deadline=Date.now()+4000;while(!existsSync(waiting)){if(Date.now()>deadline)throw new Error("Held outbound provider did not start");await new Promise(done=>setTimeout(done,20));}
      await a.getByRole("button",{name:`Remove ${names.b}`,exact:true}).press("Enter");await a.getByRole("button",{name:"Confirm removal",exact:true}).press("Enter");await a.getByRole("status").filter({hasText:`${names.b} is now inactive`}).waitFor();writeFileSync(release,"release");
      await b2.getByRole("alert").filter({hasText:"The provider could not complete this lookup. Retry or add manually."}).waitFor();check(await b2.locator('input[name="reviewHandle"]').count()===0,"removed participant receives no held provider review identity");
      check(existsSync(returned),"normal provider response was released rather than timing out");check(f.db.prepare("SELECT count(*) AS n FROM metadata_reviews WHERE payload LIKE '%YtHolding01%'").get().n===0,"removed member receives no persisted provider review");
      check(f.db.prepare("SELECT archived FROM titles WHERE id=?").get(series).archived===0,"sole contributor removal does not archive title");
      await b.goto(f.origin+"/watchlist");await b.getByRole("heading",{name:"Group access unavailable",exact:true}).waitFor();await a.goto(f.origin+"/pick");check(await a.getByRole("checkbox",{name:names.b,exact:true}).count()===0,"removed member excluded from new viewers");await detail(a,movie);await a.getByRole("article",{name:names.b,exact:true}).waitFor();
      await detail(b2,movie);await b2.getByRole("heading",{name:"Group access unavailable",exact:true}).waitFor();
      await b.goto(invite);await b.waitForURL("**/access-error");
      await b.goto(beforeRemovalLink);await b.waitForURL("**/account");await capture(contexts[1]);await b.getByRole("button",{name:`Join ${names.g1}`,exact:true}).press("Enter");await b.locator("main section").filter({has:b.getByRole("heading",{name:"Your account groups",exact:true})}).getByRole("alert").filter({hasText:"context changed"}).waitFor();await b.waitForFunction(label=>Array.from(document.querySelectorAll("button")).some(button=>button.textContent===label&&!button.disabled),`Join ${names.g1}`);
      await detail(a,movie);await a.getByRole("article",{name:names.b,exact:true}).getByText("Inactive participant",{exact:true}).waitFor();
      const afterRemovalLink=await rotate(a);await a.getByRole("link",{name:"Watchlist",exact:true}).press("Enter");await a.goBack();check(await a.getByLabel("New invite link").count()===0,"departure/back does not restore raw invite");
      await b2.goto(f.origin+"/account");await b2.getByText("This invitation is unavailable or expired. Open a current invitation link and try again.",{exact:true}).waitFor();
      await join(b,afterRemovalLink,names.g1);check(f.db.prepare("SELECT id FROM members WHERE group_id=? AND name=?").get(g1,names.b).id===member,"rejoin keeps stable member");check(JSON.stringify(f.db.prepare("SELECT * FROM progress WHERE member_id=? ORDER BY title_id").all(member))===history,"rejoin retains progress");
      const secondCookies=await contexts[4].cookies(),replayHeaders={...oldMutation.headers,origin:f.origin,cookie:secondCookies.map(cookie=>`${cookie.name}=${cookie.value}`).join("; ")};for(const key of["host","content-length","connection"])delete replayHeaders[key];
      const replay=await fetch(f.origin+"/watchlist/"+movie,{method:"POST",headers:replayHeaders,body:oldMutation.body,signal:AbortSignal.timeout(15000)});check((await replay.text()).includes("Your rating is unavailable"),"another browser's rejoin does not revive old action");check(f.db.prepare("SELECT score FROM ratings WHERE title_id=? AND member_id=?").get(movie,member).score===5,"rejected old action preserves rating");
      await detail(b2,movie);const freshRating=b2.getByRole("region",{name:"Your rating",exact:true});await freshRating.getByLabel("Rating (1–10)").fill("7");await submit(freshRating,"Save rating","Your whole-title rating is saved.");check(f.db.prepare("SELECT score FROM ratings WHERE title_id=? AND member_id=?").get(movie,member).score===7,"fresh second-browser context works after rejoin");
      await a.goto(f.origin+"/account");await a.getByRole("button",{name:"Use separate legacy access",exact:true}).press("Enter");await a.waitForURL(url=>url.pathname==="/");await capture(contexts[0]);const legacyWriter=new DatabaseSync(f.path);let legacy;try{legacy=createLegacyGroup(legacyWriter,`Explicit legacy ${width}`,f.origin).inviteUrl;}finally{legacyWriter.close();}f.secrets.push(legacy.split("/").at(-1));await a.goto(legacy);await a.waitForURL("**/group");await capture(contexts[0]);await a.getByLabel("Your name",{exact:true}).fill(names.a);await a.getByRole("button",{name:"Create and select profile",exact:true}).press("Enter");await a.getByRole("button",{name:`${names.a} Active`,exact:true}).waitFor();
      await open(a,names.g1);await f.restart();await a.reload();await a.getByRole("heading",{name:names.g1,exact:true}).waitFor();await a2.reload();await a2.getByRole("heading",{name:names.g2,exact:true}).waitFor();
      for(const page of[a,b,c,a2]){check(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),"responsive no overflow");check(await page.evaluate(()=>localStorage.length===0&&sessionStorage.length===0),"no web storage secrets");}await a.keyboard.press("Tab");
    });
    await step(`${width}: same owner recovery preserves memberships/history and revokes every old session`,async()=>{
      const account=f.db.prepare("SELECT * FROM accounts WHERE username=?").get(names.a);
      const history=JSON.stringify(f.db.prepare("SELECT * FROM progress ORDER BY title_id,member_id").all());
      const next=randomBytes(24).toString("base64url");f.secrets.push(next);
      await a.goto(f.origin+"/recover");await a.getByLabel("Username",{exact:true}).fill(names.a);await a.getByLabel("Saved recovery code").fill(recoveryCode);await a.getByLabel("New password").fill(next);await a.getByLabel("Confirm password").fill(next);await a.getByRole("button",{name:"Reset password",exact:true}).press("Enter");
      await a.getByLabel("Private recovery code").waitFor();const replacement=await a.getByLabel("Private recovery code").inputValue();f.secrets.push(replacement);check(replacement!==recoveryCode,"replacement private proof differs");
      await a2.goto(f.origin+"/account");await a2.waitForURL("**/login");
      await login(a,names.a,next);await open(a,names.g1);
      check(f.db.prepare("SELECT id FROM accounts WHERE username=?").get(names.a).id===account.id,"recovery preserves owner ID");check(JSON.stringify(f.db.prepare("SELECT * FROM progress ORDER BY title_id,member_id").all())===history,"recovery preserves actual personal history");
      await a.getByRole("button",{name:`Remove ${names.b}`,exact:true}).press("Enter");await a.getByRole("button",{name:"Confirm removal",exact:true}).press("Enter");await a.getByRole("status").filter({hasText:`${names.b} is now inactive`}).waitFor();
      await verifyAccountStorage(f,{page:a,removed:b,group:names.g1,title:movie,providerTitle:`Account provider ${width}`,width});
    });
    for(const context of contexts)await context.close();
  }
  await f.audit();
}catch(error){failure=error;}finally{try{await f?.cleanup();}catch(error){failure??=error;}}
if(failure)throw new Error(`FAIL ${current}: ${safeDiagnostic(failure,f?.secrets??[],f?.root??"",f?[f.sentinelRoot]:[])}; owned cleanup complete: ${f?.cleanupComplete??false}`);
const report={pass:true,widths:[375,1280],threeAccountsTwoGroups:true,independentSelectionStaleReplay:true,allOwnHistory:true,lookupPicker:true,removalRejoinLegacyRestart:true,sameOwnerRecoveryAndAuthenticatedWalRestore:true,privacyAudit:true,ownedCleanup:f.cleanupComplete};console.log(JSON.stringify(report));return report;
}
if(process.argv[1]&&scriptURL(resolveScriptPath(process.argv[1])).href===import.meta.url)runAccountGroups().catch(error=>{console.error(error.message);process.exitCode=1;});
